CREATE TABLE IF NOT EXISTS public.support_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, subject text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','IN_PROGRESS','CLOSED')), created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.support_requests ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.support_requests FROM anon, authenticated; GRANT INSERT ON public.support_requests TO service_role; GRANT SELECT, UPDATE, DELETE ON public.support_requests TO authenticated; DROP POLICY IF EXISTS support_admin_only ON public.support_requests; CREATE POLICY support_admin_only ON public.support_requests FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
